    asciiSet makeASCIISet(gocpp::string chars)
    {
        asciiSet as;
        for(auto i = 0; i < len(chars); i++)
        {
            auto c = chars[i];
            as[c / 32] |= 1 << (c % 32);
        }
        return as;
    }

